    historicalContext: '二十世纪中国历经革命、抗战与社会巨变，中西文化激烈碰撞，如何接续传统又走向现代成为哲学的根本课题。冯友兰以现代逻辑分析重释宋明理学，其哲学史写作恰与中国哲学的学科化同步而行。',
    famousQuotes: ['阐旧邦以辅新命', '极高明而道中庸', '照着讲与接着讲', '哲学是人生的系统反思'],
