    biography: '1135年生于西班牙科尔多瓦，因穆瓦希德王朝的宗教迫害随家流亡北非，1165年曾朝觐耶路撒冷，后定居埃及福斯塔特。早年靠家族经商维持生计，后任宫廷御医，侍奉萨拉丁的重臣，并成为埃及犹太社群的领袖（纳吉德）。1178年完成律法巨著《密西那托拉》，1190年完成《迷途指津》。1204年病逝于福斯塔特，遗体迁葬太巴列。',
