    coreIdea: '真实的人生存在于“我与你”的关系之中：人或者把他人当作经验与利用对象的“它”，或者以整全生命与之相遇的“你”。上帝是“永恒之你”，不在彼岸，而在每一次真诚相遇中低语。对话而非独白，才是精神生活的根基，教育、政治与信仰皆应由此重建。',
    biography: '1878年生于维也纳，三岁父母离异，十岁起由祖父、著名米德拉什学者所罗门·布伯抚养。青年时代求学于维也纳、柏林等地，早年投身犹太复国主义运动，后转向文化复国主义与哈西德研究。1923年出版《我与你》，又在法兰克福与罗森茨威格合作重译《圣经》。1938年移居耶路撒冷，任希伯来大学教授，晚年致力于犹太—阿拉伯和解，1965年病逝。',
