    historicalContext: '十八世纪上半叶，法国仍处于路易十五治下的专制王权与森严等级制度之中，出版审查严酷。英国光荣革命后的君主立宪与洛克的分权学说传入，成为启蒙者眼中的范本。孟德斯鸠的政体研究正是对旧制度危机的理性回应。',
